    11	
    12	    enum ImmersionState { case closed, opening, open }
    13	    var immersion: ImmersionState = .closed
    14	
    15	    /// Index of the current sky in `SpatialImageEnvironment.catalog`. Restored across
    16	    /// launches by NAME (not index) so catalog additions/reorders don't shift the selection.
    17	    var currentScene: Int = 0
    18	
    19	    private static let lastSceneKey = "lastSceneName"
