    42	    /// Show a specific sky by catalog index, masked by the §7b whiteout flash.
    43	    func selectScene(_ index: Int) {
    44	        let n = SpatialImageEnvironment.catalog.count
    45	        guard n > 0 else { return }
    46	        let idx = ((index % n) + n) % n
    47	        currentScene = idx
    48	        UserDefaults.standard.set(
    49	            SpatialImageEnvironment.catalog[idx].name, forKey: Self.lastSceneKey)
    50	        maskedSwap { [weak self] in self?.applyScene(idx) }
    51	    }
    52	
    53	    /// Jump to a random *different* sky. Uses a shuffle bag so every sky is visited once
    54	    /// before any repeat (independent random draws clustered on a few). No determinism
    55	    /// requirement here — this is a user action, not generation (§5 applied to the retired
    56	    /// generated scene).
    57	    func randomScene() {
    58	        let n = SpatialImageEnvironment.catalog.count
    59	        guard n > 1 else { if n == 1 { selectScene(0) }; return }
    60	        if sceneBag.isEmpty {
    61	            var bag = Array(0..<n).shuffled()
    62	            if bag.last == currentScene { bag.swapAt(0, n - 1) }   // no immediate repeat
    63	            sceneBag = bag
    64	        }
    65	        selectScene(sceneBag.removeLast())
    66	    }
