    68	    private var sceneBag: [Int] = []
    69	
    70	    /// Load the sky into the sphere. Falls through to the mono skybox if the stereo material
    71	    /// or an eye can't load (SpatialImageEnvironment handles that).
    72	    private func applyScene(_ index: Int) {
    73	        guard let sceneRoot else { return }
    74	        Task { @MainActor in await SpatialImageEnvironment.load(index: index, into: sceneRoot) }
