    77	    /// Run `swap` under the peak of the §7b whiteout flash. Applies immediately if the overlay
    78	    /// isn't mounted yet (e.g. a scene chosen from the launcher before entering the space).
    79	    private func maskedSwap(_ swap: @escaping @MainActor () -> Void) {
    80	        guard let whiteout else { swap(); return }
