     5	/// Hosts the RealityKit scene. Since the generated L1–L4 pipeline was retired, the scene is
     6	/// now a single `SpatialImageEnvironment` (a stereo-image inward sphere) plus the §7b whiteout
     7	/// overlay used to mask scene changes. Spec: §7 hand tracking.
     8	struct ImmersiveView: View {
     9	    @Environment(AppModel.self) private var model
    10	    @Environment(\.openWindow) private var openWindow
    11	
    12	    var body: some View {
    13	        RealityView { content, attachments in
    14	            // Register the ECS components/systems the spatial scene still uses.
    15	            ClockComponent.registerComponent()
    16	            WhiteoutComponent.registerComponent()
    17	            AnimationClockSystem.registerSystem()
    18	            WhiteoutSystem.registerSystem()
    19	
    20	            // Persistent container holds the scene; a scene change swaps the sky under it.
    21	            let container = Entity()
    22	            container.name = "SceneContainer"
    23	            content.add(container)
    24	            model.sceneContainer = container
    25	
    26	            // The spatial-image environment — an empty container mounted now (so a select
    27	            // works immediately) whose skybox loads async and can be swapped (currentScene).
    28	            let scene = SpatialImageEnvironment.makeContainer()
    29	            container.addChild(scene)
    30	            model.sceneRoot = scene
    31	            Task { @MainActor in
    32	                await SpatialImageEnvironment.load(index: model.currentScene, into: scene)
    33	            }
    34	
    35	            // §7b whiteout overlay — a persistent inward white sphere (alpha 0) a jump flashes.
    36	            let whiteout = WhiteoutSystem.makeEntity()
    37	            container.addChild(whiteout)
    38	            model.whiteout = whiteout
    39	
    40	            // Hidden control panel, revealed by the two-hand pinch-spread gesture (§7).
    41	            if let panel = attachments.entity(for: "controlPanel") {
    42	                panel.isEnabled = false
    43	                container.addChild(panel)
    44	            }
    45	        } update: { _, _ in
    46	            // Scene changes are driven imperatively via AppModel (it mutates the container).
    47	        } attachments: {
    48	            Attachment(id: "controlPanel") {
    49	                ControlPanelView().environment(model)
    50	            }
    51	        }
    52	        .task { await runHandTracking() }   // §7 reveal gesture
    53	        .upperLimbVisibility(.visible)
    54	    }
    55	
    56	    /// ARKit hand-tracking loop (90 Hz on v26+). Feeds the §7 double-pinch detector, which
    57	    /// reopens the launcher menu — the only way back to UI once its window has been closed.
    58	    /// (§7's gaze-conflict mitigation is deferred: with no window open there's nothing for
    59	    /// the first pinch's system-tap to land on, which is exactly the reopen case.)
    60	    private func runHandTracking() async {
    61	        guard HandTrackingProvider.isSupported else { return }
    62	        let session = ARKitSession()
    63	        let hands = HandTrackingProvider()
    64	        do { try await session.run([hands]) } catch { return }
    65	
    66	        // One detector per hand so alternating-hand pinches don't pair into a "double".
    67	        let detectors: [HandAnchor.Chirality: DoublePinchDetector] =
    68	            [.left: DoublePinchDetector(), .right: DoublePinchDetector()]
    69	        for d in detectors.values {
    70	            d.onDoublePinch = { openWindow(id: "launcher") }
    71	        }
    72	
    73	        for await update in hands.anchorUpdates where update.event == .updated {
    74	            let anchor = update.anchor
    75	            guard anchor.isTracked, let skeleton = anchor.handSkeleton else { continue }
    76	            let thumb = skeleton.joint(.thumbTip)
    77	            let index = skeleton.joint(.indexFingerTip)
    78	            guard thumb.isTracked, index.isTracked else { continue }
    79	            // Same-hand tip distance — anchor space suffices, no world transform needed.
    80	            detectors[anchor.chirality]?.ingest(
    81	                thumbTip: translation(of: thumb.anchorFromJointTransform),
    82	                indexTip: translation(of: index.anchorFromJointTransform),
    83	                time: update.timestamp)
    84	        }
    85	    }
    86	
    87	    private func translation(of m: simd_float4x4) -> SIMD3<Float> {
    88	        SIMD3(m.columns.3.x, m.columns.3.y, m.columns.3.z)
    89	    }
    90	}
