     6	/// §7 — reveal gesture. Two thumb+index pinch/release cycles within ~350–450 ms.
     7	/// WARNING: a single pinch is the system "tap" — arm this only when gaze is off UI (§7).
     8	@MainActor
     9	final class DoublePinchDetector {
    10	    var onDoublePinch: (() -> Void)?
    11	
    12	    // Hysteresis thresholds (metres) so one slow pinch isn't read as two.
    13	    private let pinchOn: Float = 0.015
    14	    private let pinchOff: Float = 0.03
    15	    /// Max gap between the two pinch *releases* (§7: two cycles inside ~350–450 ms).
    16	    private let window: Double = 0.45
    17	
    18	    private var isPinched = false
    19	    private var lastReleaseTime: Double?
    20	
    21	    func ingest(thumbTip: SIMD3<Float>, indexTip: SIMD3<Float>, time: Double) {
    22	        let d = simd_distance(thumbTip, indexTip)
    23	        if isPinched {
    24	            guard d > pinchOff else { return }
    25	            isPinched = false
    26	            if let prev = lastReleaseTime, time - prev <= window {
    27	                lastReleaseTime = nil
    28	                onDoublePinch?()
    29	            } else {
    30	                lastReleaseTime = time
    31	            }
    32	        } else if d < pinchOn {
    33	            isPinched = true
    34	            // A first release too old to pair with the cycle starting now is stale.
    35	            if let prev = lastReleaseTime, time - prev > window { lastReleaseTime = nil }
    36	        }
    37	    }
    38	}
    39	
